export interface Release { tag: string; draft?: boolean; prerelease?: boolean; }

export function newest(releases: readonly Release[]): string | null {
  const usable = releases.filter((r) => !r.draft);
  return usable.length > 0 ? usable[0]!.tag : null;
}

