import { expect, test } from "bun:test";
import { newest } from "./subject.js";

test("highest version wins regardless of order", () => {
  expect(newest([{ tag: "v26.9.10" }, { tag: "v26.9.11" }, { tag: "v26.9.9" }])).toBe("v26.9.11");
});
test("numeric, not lexical", () => {
  expect(newest([{ tag: "v26.9.9" }, { tag: "v26.10.0" }, { tag: "v26.9.11" }])).toBe("v26.10.0");
});
test("drafts, prereleases and junk are skipped", () => {
  expect(newest([{ tag: "v27.0.0", draft: true }, { tag: "v26.12.0", prerelease: true },
                 { tag: "nightly" }, { tag: "v26.9.11" }])).toBe("v26.9.11");
});
test("nothing usable is null", () => {
  expect(newest([{ tag: "nightly" }])).toBeNull();
});
